import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.RQXGjTIX.js";const o="/appliedcraftedenergistics/interface-block.png",i="/appliedcraftedenergistics/interface-textures.png",g=JSON.parse('{"title":"ME 气体接口","description":"","frontmatter":{},"headers":[],"relativePath":"guide/interface.md","filePath":"guide/interface.md"}'),l={name:"guide/interface.md"};function n(s,t,c,h,p,u){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="me-气体接口" tabindex="-1">ME 气体接口 <a class="header-anchor" href="#me-气体接口" aria-label="Permalink to &quot;ME 气体接口&quot;">​</a></h1><p>ME 气体接口是&quot;网络 ↔ 真实气体世界&quot;的正式接口。它是一台机器方块，会把相邻的 气体储罐 / 管路当作邻居，同时用一只<strong>真实的缓冲罐</strong>与它们交换气体。</p><p><img src="'+o+'" alt="ME 气体接口方块"></p><h2 id="内部缓冲罐" tabindex="-1">内部缓冲罐 <a class="header-anchor" href="#内部缓冲罐" aria-label="Permalink to &quot;内部缓冲罐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>体积</td><td>8,000 L</td><td>可在配置里修改</td></tr><tr><td>最大承压</td><td>24 atm（2.4 MPa）</td><td>CCB 的硬上限</td></tr><tr><td>物理容量</td><td>192,000 GU</td><td>8,000 L × 24 atm</td></tr><tr><td>供给压力</td><td>100 kPa（1 atm）</td><td>GUI 可调，每格 100 kPa，上限 1,600 kPa</td></tr></tbody></table><p>六个面使用同一张 16×16 可连接贴图：</p><p><img src="'+i+'" alt="接口贴图三面一致"></p><p>&quot;供给压力&quot;指的是<strong>AE 侧把缓冲罐补到多少压力</strong>：调高它，缓冲罐里的气就能顶住更高的管路压力， 从而把气&quot;压&quot;进相邻的高压管；调低它，则只适合低压设备。</p><h2 id="四种模式" tabindex="-1">四种模式 <a class="header-anchor" href="#四种模式" aria-label="Permalink to &quot;四种模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td><strong>导入</strong></td><td>把缓冲罐里的气体收进 ME 网络</td></tr><tr><td><strong>导出</strong></td><td>把网络里的气体放进缓冲罐，供相邻管路取走</td></tr><tr><td><strong>双向</strong></td><td>两个方向都允许</td></tr><tr><td><strong>关闭</strong></td><td>停止与 ME 网络交换</td></tr></tbody></table><p>模式按钮在 GUI 顶部，点击循环切换。</p><h2 id="与-ccb-管路的关系" tabindex="-1">与 CCB 管路的关系 <a class="header-anchor" href="#与-ccb-管路的关系" aria-label="Permalink to &quot;与 CCB 管路的关系&quot;">​</a></h2><p>接口在 CCB 眼里就是一只<strong>普通的气体储罐</strong>：有体积、有压力、遵守质量守恒。 因此：</p><ul><li>CCB 的泵、阀门、管路可以直接把气打进接口，也可以从接口抽气；</li><li>接口不会凭空产生压力，也不会把相邻储罐压过 16 atm 安全线（供给压力本身可调，但受 CCB 硬上限约束）；</li><li>当缓冲罐达到当前供给压力时，AE 侧会停止注入，GUI 会显示&quot;阻塞 / 过压&quot;提示。</li></ul><h2 id="速率与耗电" tabindex="-1">速率与耗电 <a class="header-anchor" href="#速率与耗电" aria-label="Permalink to &quot;速率与耗电&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th></tr></thead><tbody><tr><td>每 tick 搬运上限</td><td>1,000 GU/t</td></tr><tr><td>待机耗电</td><td>8 AE/t</td></tr><tr><td>搬运耗电</td><td>1.0 AE / kGU</td></tr></tbody></table><p>全部可在 <a href="/appliedcraftedenergistics/guide/config.html">配置文件</a> 中调整。</p><h2 id="gui-读什么" tabindex="-1">GUI 读什么 <a class="header-anchor" href="#gui-读什么" aria-label="Permalink to &quot;GUI 读什么&quot;">​</a></h2><ul><li>缓冲罐：气体名称 + 存量 / 容量（kGU）；</li><li>压力：当前压力 / 承压上限（kPa / MPa，和 CCB 的气压表一致）；</li><li>模式与供给压力；</li><li>状态提示：过压、阻塞。</li></ul><div class="warning custom-block"><p class="custom-block-title">它不会主动把气推给 AE2 的 ME 接口</p><p>ME 接口（AE2 的方块）按 AE2 的设计不&quot;推&quot;东西——相邻的管道或机器来抽。 本模组给 AE2 的 ME 接口注册了 CCB 气体能力，所以 <strong>CCB 的管道可以直接从 ME 接口抽气</strong>； 而 AE2 的输入总线 / 输出总线 / 存储总线 / 样板供应器则通过标准策略直接与 CCB 交互， 不需要接口作为中间层。</p></div>',20)])])}const m=a(l,[["render",n]]);export{g as __pageData,m as default};
